-- Generic SQL Export (MySQL/SQLite) for pokemon_species
CREATE TABLE IF NOT EXISTS pokemon_species (
    id INT PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    types VARCHAR(255) NOT NULL, -- Comma-separated list
    hp INT NOT NULL,
    attack INT NOT NULL,
    defense INT NOT NULL,
    speed INT NOT NULL,
    sprite VARCHAR(1000) NOT NULL,
    rarity VARCHAR(50) NOT NULL,
    gold_per_hour INT NOT NULL
);

